-- Phase B: assignment-scoped immutable quiz scoring contract.
-- Extend the snapshot builder with protected quiz questions/options at assignment time.
create or replace function public.crew_assignment_snapshot(p_journey_id uuid) returns jsonb language sql security definer set search_path=public as $$
 select jsonb_build_object('journey',(select to_jsonb(j)-'created_by' from public.crew_journeys j where j.id=p_journey_id),'modules',coalesce((select jsonb_agg(jsonb_build_object('module',to_jsonb(m),'lessons',coalesce((select jsonb_agg(jsonb_build_object('lesson',to_jsonb(l),'blocks',coalesce((select jsonb_agg(to_jsonb(b) order by b.sort_order) from public.crew_lesson_blocks b where b.lesson_id=l.id),'[]'::jsonb),'quiz',case when q.id is null then null else jsonb_build_object('id',q.id,'title',q.title,'passing_score',q.passing_score,'required',q.required,'questions',coalesce((select jsonb_agg(jsonb_build_object('id',qq.id,'prompt',qq.prompt,'question_type',qq.question_type,'explanation',qq.explanation,'sort_order',qq.sort_order,'options',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'label',o.label,'sort_order',o.sort_order,'is_correct',o.is_correct) order by o.sort_order) from public.crew_quiz_options o where o.question_id=qq.id),'[]'::jsonb)) order by qq.sort_order) from public.crew_quiz_questions qq where qq.quiz_id=q.id),'[]'::jsonb)) end) order by l.sort_order) from public.crew_lessons l left join public.crew_quizzes q on q.lesson_id=l.id and q.status='published' where l.module_id=m.id),'[]'::jsonb)) order by m.sort_order) from public.crew_journey_modules m where m.journey_id=p_journey_id),'[]'::jsonb));
$$;
revoke all on function public.crew_assignment_snapshot(uuid) from public,anon,authenticated;
